def caesar(s, k):
    out = ''
    for ch in s:
        if 'a' <= ch <= 'z':
            out += chr((ord(ch) - 97 + k) % 26 + 97)
        elif 'A' <= ch <= 'Z':
            out += chr((ord(ch) - 65 + k) % 26 + 65)
        else:
            out += ch
    return out
enc = caesar('Hello, World!', 3)
print(enc)
print(caesar(enc, -3))
