def nums(n):
    i = 0
    while i < n:
        yield i
        i += 1
def evens(src):
    for v in src:
        if v % 2 == 0:
            yield v
def squares(src):
    for v in src:
        yield v * v
print(list(squares(evens(nums(10)))))
print(sum(squares(evens(nums(8)))))
